// ── SITE SEARCH (homepage) ──
// One box for the whole site: posts and library guides, Workshop apps,
// guides and printables, Stack resources and the section pages.
// search-index.json is generated by scripts/build-search.js and loaded the
// first time the box is used. Every typed word must start a word in the
// entry (title, type, description, section or keywords); title matches
// rank first. Results carry their section's color.
(function () {
  const $ = id => document.getElementById(id);
  const input = $('ssQuery'), results = $('ssResults'), status = $('ssStatus');
  if (!input || !results) return;

  const SECTIONS = {
    continuum: 'The Continuum', workshop: 'The Workshop', locker: 'The Evidence Locker',
    flightdeck: 'From the Flight Deck', stack: 'The Stack', site: 'The Critical Vector',
  };
  const SHOW = 40;
  const words = s => s.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').split(/[^a-z0-9]+/).filter(Boolean);
  const hits = (tokens, term) => tokens.some(t => t.startsWith(term));

  let items = null, loading = null;
  function load() {
    if (!loading) {
      loading = fetch(new URL('search-index.json', document.baseURI), { cache: 'no-cache' })
        .then(r => r.json())
        .then(list => {
          items = list.map(i => ({ ...i, title: words(i.t), all: words([i.t, i.y, i.m, SECTIONS[i.s] || '', i.k].join(' ')) }));
        })
        .catch(() => { status.textContent = 'Search is unavailable right now.'; });
    }
    return loading;
  }

  function el(tag, cls, text) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;
    return e;
  }

  function render(list) {
    results.textContent = '';
    list.slice(0, SHOW).forEach(i => {
      const a = el('a', 'post-row' + (i.s !== 'site' ? ' ' + i.s + '-row' : ''));
      a.href = i.h;
      if (i.x) { a.target = '_blank'; a.rel = 'noopener'; }
      const info = el('div', 'post-info');
      info.append(
        el('div', 'post-type' + (i.s !== 'site' ? ' ' + i.s + '-type' : ''), (SECTIONS[i.s] || '') + ' · ' + i.y),
        el('div', 'post-title', i.t),
        el('div', 'post-meta', i.m));
      a.append(info, el('span', 'post-arrow', i.x ? '↗' : '›'));
      results.appendChild(a);
    });
  }

  async function search() {
    const terms = words(input.value);
    if (!terms.length) { results.hidden = true; status.textContent = ''; return; }
    if (!items) { status.textContent = 'Loading…'; await load(); if (!items) return; }
    if (words(input.value).join(' ') !== terms.join(' ')) return;  // typed on while loading
    const found = items
      .filter(i => terms.every(t => hits(i.all, t)))
      .map(i => ({ i, score: terms.filter(t => hits(i.title, t)).length }))
      .sort((a, b) => b.score - a.score)
      .map(x => x.i);
    results.hidden = found.length === 0;
    render(found);
    status.textContent = found.length === 0 ? 'Nothing matches. Try a shorter word.'
      : found.length === 1 ? '1 result'
      : found.length > SHOW ? `${found.length} results, showing the first ${SHOW}. Add a word to narrow it.`
      : found.length + ' results';
  }

  input.addEventListener('focus', load, { once: true });
  input.addEventListener('input', search);
  input.addEventListener('keydown', e => { if (e.key === 'Escape') { input.value = ''; search(); } });
  const q = new URLSearchParams(location.search).get('q');
  if (q) input.value = q;
  if (input.value) search();
})();
